<div class="top"><div><h2 style="margin:0"><?= e($c['number']) ?></h2><span class="muted">Against <a href="/staff/invoices/<?= (int) $c['invoice_id'] ?>"><?= e($c['inumber']) ?></a> &middot; <?= e($c['bill_name']) ?> &middot; <?= e(fmt_date($c['issue_date'])) ?></span></div><div><a class="btn alt" href="/staff/credit-notes/<?= (int) $c['id'] ?>.pdf">Download PDF</a> <a class="btn alt" href="/staff/credit-notes">&larr; All</a></div></div>
<div class="grid g2" style="align-items:start"><div class="card"><dl class="kv"><dt>Reason</dt><dd><?= e($c['reason']) ?></dd><dt>Amount</dt><dd><?= e(money($c['subtotal'])) ?></dd><dt>GST</dt><dd><?= e(money($c['cgst'] + $c['sgst'] + $c['igst'])) ?> (<?= $c['tax_kind'] === 'igst' ? 'IGST' : 'CGST + SGST' ?>)</dd><dt>Total credit</dt><dd><b><?= e(money($c['total'])) ?></b></dd><dt>Invoice balance now</dt><dd><?= e(money($balance)) ?></dd><dt>Refund</dt><dd><?= $c['refunded_on'] ? 'Refunded ' . e(fmt_date($c['refunded_on'])) . ' by ' . e((string) $c['refund_method']) . ($c['refund_ref'] ? ' (' . e($c['refund_ref']) . ')' : '') : 'not refunded' ?></dd></dl>
<?php if ($c['bill_email']): ?><form method="post" class="mt"><?= csrf_field() ?><input type="hidden" name="action" value="email"><button class="btn alt sm" data-confirm="E-mail this credit note to <?= e($c['bill_email']) ?>?">E-mail to customer</button></form><?php endif; ?></div>
<?php if (!$c['refunded_on'] && $paid > 0 && $balance < 0): ?><div class="card"><h3>Record the refund</h3><p class="muted">The customer has paid more than is now due (<?= e(money(-$balance)) ?>). When you refund them, record it here.</p><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="refund"><div class="row"><div><label>Date</label><input type="date" name="refunded_on" value="<?= e(date('Y-m-d')) ?>" required></div><div><label>Method</label><select name="method"><?= options(PAY_METHODS) ?></select></div><div><label>Reference</label><input name="ref" maxlength="60"></div></div><button class="btn">Record refund</button></form></div><?php endif; ?></div>
